-- Phase 60: Customer 360 is a derived read/intelligence layer. Canonical customer, CRM, loyalty, orders, support and conversations remain sources of truth.
-- quality: allow-nonconcurrent-index reason=new-empty-phase60-tables
alter table public.plans add column if not exists customer_360_enabled boolean not null default true,add column if not exists customer_health_enabled boolean not null default true,add column if not exists customer_next_best_action_enabled boolean not null default true,add column if not exists customer_identity_resolution_enabled boolean not null default true,add column if not exists customer_ai_summary_enabled boolean not null default true;
alter table public.store_feature_flags add column if not exists customer_360_enabled boolean not null default true,add column if not exists customer_health_enabled boolean not null default true,add column if not exists customer_next_best_action_enabled boolean not null default true,add column if not exists customer_identity_resolution_enabled boolean not null default true,add column if not exists customer_ai_summary_enabled boolean not null default true;

create table public.customer360_member_permissions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,permissions text[] not null default '{customer360:view}',scope_type text not null default 'store' check(scope_type in('organization','network','region','store')),scope_id uuid,active boolean not null default true,updated_by uuid references auth.users(id),updated_at timestamptz not null default now());
create unique index customer360_permission_scope_idx on public.customer360_member_permissions(organization_id,user_id,scope_type,coalesce(scope_id,'00000000-0000-0000-0000-000000000000'::uuid));
create table public.customer360_field_registry(field_key text primary key,label text not null,section text not null,source_type text not null,required_permission text,pii boolean not null default false,sensitive boolean not null default false,roles text[] not null default '{}',masking_policy text,active boolean not null default true);
