create table public.customer_360_summaries(organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,preferred_store_id uuid references public.establishments(id) on delete set null,first_order_at timestamptz,last_order_at timestamptz,orders_count bigint not null default 0,lifetime_revenue_cents bigint not null default 0,average_ticket_cents bigint not null default 0,last_interaction_at timestamptz,preferred_channel text,loyalty_status text,loyalty_points bigint not null default 0,open_support_cases_count integer not null default 0,active_subscription_count integer not null default 0,churn_risk_level text check(churn_risk_level is null or churn_risk_level in('healthy','attention','at_risk','inactive','insufficient_data')),relationship_value_band text check(relationship_value_band is null or relationship_value_band in('new','occasional','regular','high_value','dormant')),lifecycle_stage text check(lifecycle_stage is null or lifecycle_stage in('prospect','new','repeat','loyal','dormant','recovered')),data_as_of timestamptz not null default now(),source_freshness jsonb not null default '{}',updated_at timestamptz not null default now(),primary key(organization_id,customer_id));
create index customer360_summary_list_idx on public.customer_360_summaries(organization_id,lifecycle_stage,churn_risk_level,last_order_at desc);
create table public.customer360_preferences(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,preference_type text not null check(preference_type in('favorite_store','preferred_channel','fulfillment','dietary_note_explicit','communication','category_pattern','product_pattern')),value jsonb not null,origin text not null check(origin in('customer_explicit','staff_recorded','order_observed','portal','consent')),observed_label boolean not null default false,active boolean not null default true,created_by uuid references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,customer_id,preference_type),check(preference_type not in('category_pattern','product_pattern') or observed_label));
create table public.customer_identity_candidates(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,source_customer_id uuid not null references public.customers(id) on delete cascade,target_customer_id uuid not null references public.customers(id) on delete cascade,matched_identifiers jsonb not null,confidence numeric(5,4) not null check(confidence between 0 and 1),reason_codes text[] not null,status text not null default 'pending' check(status in('pending','merged','kept_separate','expired')),reviewed_by uuid references auth.users(id),reviewed_at timestamptz,created_at timestamptz not null default now(),check(source_customer_id<>target_customer_id),unique(organization_id,source_customer_id,target_customer_id));
create table public.customer360_merge_operations(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,store_id uuid references public.establishments(id) on delete cascade,candidate_id uuid references public.customer_identity_candidates(id) on delete set null,source_customer_id uuid not null references public.customers(id) on delete restrict,target_customer_id uuid not null references public.customers(id) on delete restrict,preview jsonb not null,rollback_snapshot jsonb not null,status text not null default 'preview' check(status in('preview','approved','merged','failed','reverted')),action_request_id uuid references public.copilot_action_requests(id) on delete set null,requested_by uuid not null references auth.users(id),confirmed_by uuid references auth.users(id),confirmed_at timestamptz,merge_audit_id uuid references public.customer_merge_audit(id) on delete set null,error_code text,created_at timestamptz not null default now(),completed_at timestamptz);
create table public.customer360_timeline_index(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,event_type text not null,occurred_at timestamptz not null,source_type text not null,source_id text not null,title text not null,summary text,metadata_safe jsonb not null default '{}',source_updated_at timestamptz,indexed_at timestamptz not null default now(),unique(organization_id,source_type,source_id,event_type));
create index customer360_timeline_cursor_idx on public.customer360_timeline_index(organization_id,customer_id,occurred_at desc,id desc);
create table public.customer_relationship_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,snapshot_at timestamptz not null,rule_version text not null,recency_days integer,frequency_orders numeric,monetary_revenue_cents bigint not null default 0,average_ticket_cents bigint not null default 0,order_cadence_days numeric,repeat_customer boolean not null default false,value_band text not null check(value_band in('new','occasional','regular','high_value','dormant')),source_freshness jsonb not null default '{}',unique(organization_id,customer_id,snapshot_at,rule_version));
create table public.customer360_lifecycle_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,from_stage text,to_stage text not null check(to_stage in('prospect','new','repeat','loyal','dormant','recovered')),reason_codes text[] not null,rule_version text not null,changed_at timestamptz not null default now());
create table public.customer360_health_snapshots(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,health text not null check(health in('healthy','attention','at_risk','inactive','insufficient_data')),reason_codes text[] not null,explanation text[] not null,signals_safe jsonb not null,rule_version text not null,probabilistic boolean not null default false,sensitive_signals_used boolean not null default false,calculated_at timestamptz not null default now());
create index customer360_health_current_idx on public.customer360_health_snapshots(organization_id,customer_id,calculated_at desc);
create table public.customer360_next_best_actions(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,action_type text not null,priority integer not null check(priority between 1 and 100),reason text not null,guardrails jsonb not null,marketing_suppressed boolean not null default false,status text not null default 'suggested' check(status in('suggested','accepted','dismissed','expired','converted_to_task')),expires_at timestamptz,created_at timestamptz not null default now(),check(marketing_suppressed or action_type not in('campaign','offer','promotional_message')));
create table public.customer360_notes(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,store_id uuid references public.establishments(id) on delete set null,note_type text not null check(note_type in('service','preference','operational','follow_up')),content text not null check(length(btrim(content)) between 2 and 1000),policy_acknowledged boolean not null default false,visibility text not null default 'restricted' check(visibility in('operational','restricted')),created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),archived_at timestamptz);
create table public.customer360_segment_history(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,segment_id uuid not null references public.crm_segments(id) on delete cascade,membership_status text not null check(membership_status in('entered','exited')),segment_rule_version text,occurred_at timestamptz not null default now());
create table public.customer360_audit_events(id bigint generated always as identity primary key,organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid references public.customers(id) on delete set null,actor_user_id uuid references auth.users(id),action text not null,reason text,before_state jsonb,after_state jsonb,metadata_safe jsonb not null default '{}',correlation_id uuid not null default gen_random_uuid(),created_at timestamptz not null default now());
create table public.customer360_refresh_jobs(id uuid primary key default gen_random_uuid(),organization_id uuid not null references public.organizations(id) on delete cascade,customer_id uuid references public.customers(id) on delete cascade,job_type text not null check(job_type in('summary','timeline','health','identity_candidates','analytics')),status text not null default 'pending' check(status in('pending','leased','completed','failed','dead_lettered')),idempotency_key text not null,attempts integer not null default 0,max_attempts integer not null default 5,available_at timestamptz not null default now(),leased_until timestamptz,last_error text,created_at timestamptz not null default now(),completed_at timestamptz,unique(organization_id,idempotency_key));

create or replace function private.enqueue_customer360_refresh() returns trigger language plpgsql security definer set search_path='' as $$
declare cid uuid:=coalesce(new.customer_id,old.customer_id); org uuid; source_store uuid:=coalesce(new.establishment_id,old.establishment_id); token text:=txid_current()::text;
begin
  if cid is null then return null; end if;
  select e.organization_id into org from public.establishments e join public.customers c on c.establishment_id=e.id where c.id=cid;
  if org is null then return null; end if;
  insert into public.customer360_refresh_jobs(organization_id,customer_id,job_type,idempotency_key) values
  (org,cid,'summary',tg_table_name||':'||token||':summary'),(org,cid,'timeline',tg_table_name||':'||token||':timeline'),(org,cid,'health',tg_table_name||':'||token||':health') on conflict do nothing;
  return null;
end $$;
revoke all on function private.enqueue_customer360_refresh() from public,anon,authenticated;
create trigger customer360_orders_refresh after insert or update on public.orders for each row execute function private.enqueue_customer360_refresh();
create trigger customer360_feedback_refresh after insert or update on public.crm_feedback for each row execute function private.enqueue_customer360_refresh();
create trigger customer360_support_refresh after insert or update on public.customer_support_requests for each row execute function private.enqueue_customer360_refresh();
create trigger customer360_reservations_refresh after insert or update on public.reservations for each row execute function private.enqueue_customer360_refresh();
create trigger customer360_subscriptions_refresh after insert or update on public.customer_subscriptions for each row execute function private.enqueue_customer360_refresh();
create trigger customer360_campaign_refresh after insert or update on public.crm_campaign_recipients for each row execute function private.enqueue_customer360_refresh();
create trigger customer360_conversation_refresh after insert or update on public.omnichannel_conversations for each row execute function private.enqueue_customer360_refresh();
insert into public.customer360_refresh_jobs(organization_id,customer_id,job_type,idempotency_key)
select e.organization_id,c.id,'summary','phase60-backfill:'||c.id::text from public.customers c join public.establishments e on e.id=c.establishment_id on conflict do nothing;

