do $$ declare t text;begin foreach t in array array['customer360_member_permissions','customer360_field_registry','customer_360_summaries','customer360_preferences','customer_identity_candidates','customer360_merge_operations','customer360_timeline_index','customer_relationship_snapshots','customer360_lifecycle_history','customer360_health_snapshots','customer360_next_best_actions','customer360_notes','customer360_segment_history','customer360_audit_events','customer360_refresh_jobs','fact_customer_relationship','fact_customer_interactions','fact_customer_health_snapshots','fact_customer_lifecycle_changes','fact_customer_identity_merges','dim_customer_lifecycle','dim_customer_health','dim_customer_value_band','dim_customer_channel_preference'] loop execute format('alter table public.%I enable row level security',t);execute format('create policy %I on public.%I for all to service_role using(true) with check(true)',left(t||'_service_only',63),t);execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
comment on table public.customer_360_summaries is 'Derived, minimal Customer 360 read model. Canonical data remains in customers, orders, CRM, loyalty, support, reservations, subscriptions and omnichannel.';
comment on table public.customer360_health_snapshots is 'Deterministic, explainable relationship health. Sensitive or psychological profiling is forbidden.';
notify pgrst,'reload schema';
